Object.assign(SNIP,{});PRESET_NOTES["l1"]={"Ví dụ: Tìm số lớn nhất": "Giải thuật “giữ lớn nhất tạm thời”: xét lần lượt từng số, gặp số lớn hơn thì thay. Mỗi phần tử được đọc đúng một lần, nên dãy n số cần khoảng n lần so sánh.", "Ví dụ: Tổng 1..n bằng cách cộng dần": "Cộng lần lượt 1, 2, …, n vào tong: vòng lặp chạy n lần. Để ý bộ đếm bước: thử đổi n = 10 thành 1000.", "Ví dụ: Tổng 1..n bằng công thức": "Công thức n(n + 1) / 2 cho kết quả ngay dù n là một tỷ. Dùng long long vì kết quả vượt phạm vi int.", "Ví dụ: Đếm và cộng các chữ số": "Mỗi lần lặp lấy chữ số cuối bằng n % 10 rồi bỏ nó đi bằng n /= 10. Số có d chữ số cần d lần lặp. Dùng do-while để n = 0 vẫn được tính là 1 chữ số.", "Ví dụ: Kiểm tra số nguyên tố (thử chia)": "Thử chia n cho mọi d từ 2 tới n - 1; chia hết thì không phải số nguyên tố. Đúng, nhưng với n là số nguyên tố lớn sẽ thử gần n lần. Bài 5 sẽ cải tiến để chỉ cần thử tới √n.", "Lỗi: vòng lặp không dừng": "Quên tăng i: điều kiện i <= n luôn đúng nên chương trình không bao giờ dừng, vi phạm tính “hữu hạn”. Trình mô phỏng dừng sau 1 000 000 bước."};EX_HINTS["l1"]=[["Công thức Gauss: 1 + 2 + … + n = n(n + 1) / 2.", "Dùng long long: với n = 10^9, kết quả khoảng 5 · 10^17, vượt xa phạm vi int.", "Nhân trước rồi mới chia: n(n + 1) luôn chẵn nên chia 2 không bị mất phần lẻ."], ["Không cần lưu cả dãy: mỗi số đọc vào chỉ cần so với lớn nhất và nhỏ nhất tạm thời.", "Khởi tạo bằng số ĐẦU TIÊN (i == 0), đừng khởi tạo bằng 0: dãy toàn số âm sẽ sai."], ["Chữ số cuối là n % 10; bỏ chữ số cuối bằng n /= 10.", "n = 0 có 1 chữ số: dùng do-while, hoặc xử lý riêng trường hợp n = 0.", "10^18 vừa với long long (tối đa khoảng 9,2 · 10^18)."]];
