const PR1=[{label:"Ví dụ: Tìm số lớn nhất",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {12, 45, 7, 33, 51, 9, 28};\n    int n = a.size();\n    int lonNhat = a[0];\n    for (int i = 1; i < n; i++) {\n        if (a[i] > lonNhat) {\n            lonNhat = a[i];\n        }\n    }\n    cout << \"Lon nhat: \" << lonNhat << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"vars",names:["lonNhat"]}],predict:[{line:11,v:"lonNhat",val:true,q:"lonNhat sẽ nhận giá trị nào? (bấm vào cột có giá trị đó)"}],py:{code:"a = [12, 45, 7, 33, 51, 9, 28]\nn = len(a)\nlonNhat = a[0]\nfor i in range(1, n):\n    if a[i] > lonNhat:\n        lonNhat = a[i]\nprint(\"Lon nhat:\", lonNhat)",predict:[{line:6,v:"lonNhat",val:true,q:"lonNhat sẽ nhận giá trị nào? (bấm vào cột có giá trị đó)"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 12, 45, 7, 33, 51, 9, 28 };\n        int n = a.Length;\n        int lonNhat = a[0];\n        for (int i = 1; i < n; i++)\n        {\n            if (a[i] > lonNhat)\n            {\n                lonNhat = a[i];\n            }\n        }\n        Console.WriteLine(\"Lon nhat: \" + lonNhat);\n    }\n}",predict:[{line:14,v:"lonNhat",val:true,q:"lonNhat sẽ nhận giá trị nào? (bấm vào cột có giá trị đó)"}]}},{label:"Ví dụ: Tổng 1..n bằng cách cộng dần",input:"10",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    long long tong = 0;\n    for (long long i = 1; i <= n; i++) {\n        tong += i;\n    }\n    cout << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","i","tong"]}],py:{code:"n = int(input())\ntong = 0\nfor i in range(1, n + 1):\n    tong += i\nprint(tong)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        long tong = 0;\n        for (long i = 1; i <= n; i++)\n        {\n            tong += i;\n        }\n        Console.WriteLine(tong);\n    }\n}"}},{label:"Ví dụ: Tổng 1..n bằng công thức",input:"1000000000",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    long long tong = n * (n + 1) / 2;\n    cout << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","tong"]}],py:{code:"n = int(input())\ntong = n * (n + 1) // 2\nprint(tong)",note:"Công thức n(n + 1) // 2 cho kết quả ngay, dù n lớn tới một tỷ. Trong Python, // là phép chia lấy phần nguyên; dùng / sẽ ra số thực (500000000500000000.0)."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        long tong = n * (n + 1) / 2;\n        Console.WriteLine(tong);\n    }\n}",note:"Công thức n(n + 1) / 2 cho kết quả ngay dù n là một tỷ. Dùng long vì kết quả vượt phạm vi int (khoảng 2,1 tỷ)."}},{label:"Ví dụ: Đếm và cộng các chữ số",input:"2026",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    int dem = 0, tong = 0;\n    do {\n        tong += n % 10;\n        dem++;\n        n /= 10;\n    } while (n > 0);\n    cout << dem << \" chu so, tong = \" << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","dem","tong"]}],py:{code:"n = int(input())\ndem = 0\ntong = 0\nwhile True:\n    tong += n % 10\n    dem += 1\n    n //= 10\n    if n == 0:\n        break\nprint(dem, \"chu so, tong =\", tong)",note:"Python không có do-while; viết while True rồi break ở cuối thân vòng lặp để thân chạy ít nhất một lần (n = 0 vẫn có 1 chữ số)."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        int dem = 0;\n        long tong = 0;\n        do\n        {\n            tong += n % 10;\n            dem++;\n            n /= 10;\n        } while (n > 0);\n        Console.WriteLine(dem + \" chu so, tong = \" + tong);\n    }\n}"}},{label:"Ví dụ: Kiểm tra số nguyên tố (thử chia)",input:"97",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    bool laNguyenTo = n >= 2;\n    for (int d = 2; d < n; d++) {\n        if (n % d == 0) {\n            laNguyenTo = false;\n            break;\n        }\n    }\n    cout << n << (laNguyenTo ? \" la\" : \" khong la\") << \" so nguyen to\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","d","laNguyenTo"]}],py:{code:"n = int(input())\nlaNguyenTo = n >= 2\nfor d in range(2, n):\n    if n % d == 0:\n        laNguyenTo = False\n        break\nprint(n, \"la\" if laNguyenTo else \"khong la\", \"so nguyen to\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        bool laNguyenTo = n >= 2;\n        for (int d = 2; d < n; d++)\n        {\n            if (n % d == 0)\n            {\n                laNguyenTo = false;\n                break;\n            }\n        }\n        Console.WriteLine(n + (laNguyenTo ? \" la\" : \" khong la\") + \" so nguyen to\");\n    }\n}"}},{label:"Lỗi: vòng lặp không dừng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n = 10, tong = 0;\n    int i = 1;\n    while (i <= n) {\n        tong += i;\n    }\n    cout << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["i","tong"]}],py:{code:"n = 10\ntong = 0\ni = 1\nwhile i <= n:\n    tong += i\nprint(tong)",note:"Quên tăng i (i += 1) nên điều kiện i <= n luôn đúng: vòng lặp chạy mãi. Trình mô phỏng dừng chương trình khi vượt giới hạn số bước."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 10, tong = 0;\n        int i = 1;\n        while (i <= n)\n        {\n            tong += i;\n        }\n        Console.WriteLine(tong);\n    }\n}"}}];
