makeEx2(document.getElementById("ex-l1"),sim1,[{t:"Tổng từ 1 đến n",d:"Đầu vào: một số nguyên n (1 ≤ n ≤ 10^9). Đầu ra: tổng 1 + 2 + … + n. Với n tới một tỷ, cách cộng dần cần quá nhiều bước: hãy dùng công thức.",tests:[{in:"10",out:"55"},{in:"1",out:"1"},{in:"100",out:"5050"},{in:"1000000000",out:"500000000500000000"},{in:"99999",out:"4999950000"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    // tính tổng 1 + 2 + ... + n\n    return 0;\n}",perf:{gen:n=>String(n),ns:[1000,100000,10000000],need:"1",limit:n=>60,why:"Cách cộng dần cần n bước. Với n = 10 triệu đã vượt giới hạn; với n = một tỷ thì không thể kịp. Dùng công thức n(n + 1) / 2."},py:{start:"n = int(input())\n# tính tổng 1 + 2 + ... + n",hints:["Công thức Gauss: 1 + 2 + … + n = n(n + 1) / 2.","Trong Python dùng // (chia lấy phần nguyên) để kết quả là số nguyên; / cho ra số thực.","Số nguyên Python không bị tràn, nhưng cộng dần tới 10^9 vẫn quá chậm: hãy dùng công thức."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        // tính tổng 1 + 2 + ... + n\n    }\n}",hints:["Công thức Gauss: 1 + 2 + … + n = n(n + 1) / 2.","Dùng long: với n = 10^9, kết quả khoảng 5 · 10^17, vượt xa phạm vi int.","Nhân trước rồi mới chia: n(n + 1) luôn chẵn nên chia 2 không bị mất phần lẻ."]}},{t:"Lớn nhất và nhỏ nhất",d:"Đầu vào: số n (1 ≤ n ≤ 10^5), rồi n số nguyên (mỗi số trong khoảng ±10^9). Đầu ra: số lớn nhất và số nhỏ nhất, cách nhau một dấu cách.",tests:[{in:"5\n3 9 -2 7 0",out:"9 -2"},{in:"1\n42",out:"42 42"},{in:"4\n-5 -5 -5 -5",out:"-5 -5"},{in:"3\n1000000000 -1000000000 0",out:"1000000000 -1000000000"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    // đọc từng số và cập nhật lớn nhất, nhỏ nhất\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%100003-50000).join(" "),ns:[1000,4000,16000],need:"n",limit:n=>12*n+100,why:"Mỗi số chỉ cần xét một lần. Nếu bạn sắp xếp hay so mỗi số với mọi số khác, số bước tăng quá nhanh."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n# duyệt từng số và cập nhật lớn nhất, nhỏ nhất",hints:["Đọc cả dòng số bằng list(map(int, input().split())).","Khởi tạo bằng số ĐẦU TIÊN a[0], đừng khởi tạo bằng 0: dãy toàn số âm sẽ sai.","Python có sẵn max(a) và min(a); thử tự viết vòng lặp trước để hiểu giải thuật."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // duyệt từng số và cập nhật lớn nhất, nhỏ nhất\n    }\n}",hints:["Dòng thứ hai chứa n số: Console.ReadLine().Split() tách thành các chuỗi, Array.ConvertAll(…, int.Parse) đổi cả mảng sang int.","Khởi tạo bằng số ĐẦU TIÊN a[0], đừng khởi tạo bằng 0: dãy toàn số âm sẽ sai.","Cộng chuỗi với số: lon + \" \" + nho in hai số cách nhau một dấu cách."]}},{t:"Số chữ số và tổng chữ số",d:"Đầu vào: số nguyên n (0 ≤ n ≤ 10^18). Đầu ra: số chữ số của n và tổng các chữ số, cách nhau một dấu cách.",tests:[{in:"2026",out:"4 10"},{in:"0",out:"1 0"},{in:"7",out:"1 7"},{in:"1000000000000000000",out:"19 1"},{in:"999999999999999999",out:"18 162"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    // lấy chữ số cuối bằng n % 10, bỏ nó bằng n /= 10\n    return 0;\n}",py:{start:"n = int(input())\n# lấy chữ số cuối bằng n % 10, bỏ nó bằng n //= 10",hints:["Chữ số cuối là n % 10; bỏ chữ số cuối bằng n //= 10 (không dùng /, sẽ ra số thực).","n = 0 có 1 chữ số: dùng while True … break ở cuối, hoặc xử lý riêng n = 0.","Cách khác: len(str(n)) và sum(map(int, str(n)))."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        // lấy chữ số cuối bằng n % 10, bỏ nó bằng n /= 10\n    }\n}",hints:["Chữ số cuối là n % 10; bỏ chữ số cuối bằng n /= 10 (chia hai số nguyên trong C# bỏ phần thập phân).","n = 0 có 1 chữ số: dùng do-while, hoặc xử lý riêng trường hợp n = 0.","10^18 vừa với long (tối đa khoảng 9,2 · 10^18). Biến tong cũng khai báo long: C# không tự đổi long (n % 10) sang int."]}}]);

